package de.mika.promptwerk;
import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;
import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.json.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35) @LooperMode(LooperMode.Mode.PAUSED)
public class Revision31Tests {
 MainActivity a;
 @Before public void setup(){RuntimeEnvironment.getApplication().getSharedPreferences("library",0).edit().clear().commit();a=Robolectric.buildActivity(MainActivity.class).setup().get();for(MainActivity.Item i:a.items)i.type="prompt";}
 @After public void close(){a.onDestroy();}
 Button find(View view,String name){if(view instanceof Button&&((Button)view).getText().toString().equals(name))return (Button)view;if(view instanceof ViewGroup)for(int n=0;n<((ViewGroup)view).getChildCount();n++){Button b=find(((ViewGroup)view).getChildAt(n),name);if(b!=null)return b;}return null;}
 MainActivity.Att attachment(String name,String mime,byte[] bytes)throws Exception{File f=File.createTempFile("test-",".bin",a.getCacheDir());try(OutputStream out=new FileOutputStream(f)){out.write(bytes);}MainActivity.Att att=new MainActivity.Att(a.digest(f),name,mime,bytes.length);File target=a.file(att);target.getParentFile().mkdirs();java.nio.file.Files.copy(f.toPath(),target.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);return att;}
 @Test public void clearButtonClearsLockedDraftAndUndoRestoresTextAndAttachments()throws Exception{MainActivity.Att att=attachment("memo.txt","text/plain","Anhang".getBytes(StandardCharsets.UTF_8));a.editor.setText("Wichtiger Entwurf");a.draftFiles.add(att);a.draftChanged();a.setHandedOver(true);Button clear=find(a.editPane,"Leeren");assertNotNull(clear);clear.performClick();assertEquals("",a.editor.getText().toString());assertTrue(a.draftFiles.isEmpty());assertFalse(a.handedOver);a.undo();assertEquals("Wichtiger Entwurf",a.editor.getText().toString());assertEquals(att.key,a.draftFiles.get(0).key);}
 @Test public void largerListButtonFitsSmallScreen(){View root=a.findViewById(android.R.id.content);root.measure(View.MeasureSpec.makeMeasureSpec(360,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(800,View.MeasureSpec.EXACTLY));root.layout(0,0,360,800);assertTrue(a.listButton.getWidth()>=a.dp(72));assertEquals(a.dp(48),a.listButton.getHeight());assertEquals(16f,a.listButton.getTextSize(),0.1f);assertTrue(a.listButton.getRight()<=((View)a.listButton.getParent()).getWidth());}
 @Test public void clipboardContainsReadableFileUriAndDoesNotAlterDraft()throws Exception{MainActivity.Att att=attachment("memo.txt","text/plain","Dateiinhalt ä".getBytes(StandardCharsets.UTF_8));a.editor.setText("Bleibt");a.copyAttachment(att);ClipData clip=((ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE)).getPrimaryClip();assertEquals(a.uri(att),clip.getItemAt(0).getUri());try(InputStream in=a.getContentResolver().openInputStream(clip.getItemAt(0).getUri())){assertEquals("Dateiinhalt ä",new String(in.readAllBytes(),StandardCharsets.UTF_8));}assertEquals("Bleibt",a.editor.getText().toString());assertFalse(a.handedOver);}
 @Test public void assignmentPersistsNormalizesAndCanBeRemoved()throws Exception{MainActivity.Item item=a.items.get(0);a.assignProject(item,"  Mein   Projekt  ");assertEquals("Mein Projekt",item.project);assertTrue(a.matches(item,"Mein Projekt"));a.assignProject(a.items.get(1),"mein projekt");assertEquals(1,a.projectNames().size());String id=item.id;MainActivity again=Robolectric.buildActivity(MainActivity.class).setup().get();MainActivity.Item restored=again.items.stream().filter(i->i.id.equals(id)).findFirst().get();assertEquals("Mein Projekt",restored.project);again.assignProject(restored,"");assertEquals("",again.parse(restored.json()).project);again.onDestroy();}
 @Test public void projectPickerSelectsExistingWithOneTapAndCancelDoesNotAssign(){MainActivity.Item one=a.items.get(0),two=a.items.get(1);a.assignProject(one,"Projekt A");a.chooseProject(two);AlertDialog dialog=ShadowAlertDialog.getLatestAlertDialog();dialog.getListView().performItemClick(null,2,2);assertEquals("Projekt A",two.project);a.chooseProject(two);ShadowAlertDialog.getLatestAlertDialog().getButton(-2).performClick();assertEquals("Projekt A",two.project);}
 @Test public void zipManifestRoundtripIncludesProjectAndLegacyStillLoads()throws Exception{MainActivity.Item item=a.items.get(0);a.assignProject(item,"Projekt mit Ä");JSONObject manifest=new JSONObject();manifest.put("format","promptwerk");manifest.put("version",3);manifest.put("items",a.data());File backup=File.createTempFile("test-backup-",".zip",a.getCacheDir());a.buildBackup(backup,manifest,new ArrayList<>());try(java.util.zip.ZipInputStream in=new java.util.zip.ZipInputStream(new FileInputStream(backup))){assertEquals("promptwerk.json",in.getNextEntry().getName());JSONObject loaded=new JSONObject(new String(in.readAllBytes(),StandardCharsets.UTF_8));assertEquals(item.project,a.parse(loaded.getJSONArray("items").getJSONObject(0)).project);}JSONObject old=item.json();old.remove("project");assertEquals("",a.parse(old).project);}
 @Test public void txtExportContainsFullActiveTextAndLosslessBinary()throws Exception{MainActivity.Item item=a.items.get(0);item.project="Export";item.archived=false;item.text="Auftrag mit Umlauten äöü\nZweite Zeile";byte[] bytes=new byte[24579];new Random(4).nextBytes(bytes);item.files.add(attachment("bild.png","image/png",bytes));item.files.add(attachment("notiz.txt","text/plain","Anhang zum Lesen".getBytes(StandardCharsets.UTF_8)));StringWriter out=new StringWriter();a.writeProject(out,"Export",new ArrayList<>(Arrays.asList(item)));String txt=out.toString();assertTrue(txt.contains(item.text));assertTrue(txt.contains("Status: Aktiv"));assertTrue(txt.contains("Anhang zum Lesen"));assertTrue(txt.contains("keine Datenschutzeinstellungen"));String binary=txt.substring(txt.indexOf("BEGIN BASE64\n")+13,txt.indexOf("\nEND BASE64"));assertArrayEquals(bytes,android.util.Base64.decode(binary,android.util.Base64.DEFAULT));assertEquals(item.text,a.items.get(0).text);}
 @Test public void corruptAttachmentFailsBeforeSuccessfulExport()throws Exception{MainActivity.Item item=a.items.get(0);item.project="Test";MainActivity.Att att=attachment("test.pdf","application/pdf",new byte[]{1,2,3});item.files.add(att);try(FileOutputStream out=new FileOutputStream(a.file(att))){out.write(new byte[]{3,2,1});}try{a.writeProject(new StringWriter(),"Test",new ArrayList<>(Arrays.asList(item)));fail("Corrupt file must fail");}catch(IOException expected){assertTrue(expected.getMessage().contains("beschädigt"));}}

 @Test public void completedEntriesAndBlocksAreExcludedFromProjectsAndTxt()throws Exception{MainActivity.Item active=a.items.get(0),done=a.items.get(1);active.project="Aktives Projekt";done.project="Nur erledigt";done.archived=true;done.text="DARF NICHT EXPORTIERT WERDEN";assertFalse(a.projectNames().contains("Nur erledigt"));MainActivity.Item block=new MainActivity.Item("BAUSTEIN NICHT EXPORTIEREN","block-text","block");block.project=active.project;StringWriter out=new StringWriter();a.writeProject(out,"Aktives Projekt",new ArrayList<>(Arrays.asList(active,done,block)));assertTrue(out.toString().contains(active.text));assertFalse(out.toString().contains(done.text));assertFalse(out.toString().contains(done.title));assertFalse(out.toString().contains(block.title));assertTrue(out.toString().contains("ARBEITSAUFTRAG AN DIE KI"));}
 @Test public void projectExportUsesTxtDocumentPicker(){a.requestProjectExport("Test/Projekt");ShadowAlertDialog.getLatestAlertDialog().getButton(-1).performClick();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();Intent started=Shadows.shadowOf(a).getNextStartedActivityForResult().intent;assertEquals(Intent.ACTION_CREATE_DOCUMENT,started.getAction());assertEquals("text/plain",started.getType());assertEquals("Promptwerk-Test_Projekt.txt",started.getStringExtra(Intent.EXTRA_TITLE));assertEquals("Test/Projekt",a.pendingProject);}
}
